import pytest
from fastapi.testclient import TestClient

OK = {'email': 'ada@example.com', 'message': 'Great service, thanks!', 'score': 9}


def test_valid_request(client: TestClient) -> None:
    r = client.post("/feedback", json=OK)
    assert r.status_code == 200
    assert r.json() == {'email': 'ada@example.com', 'message': 'Great service, thanks!', 'score': 9}


@pytest.mark.parametrize(
    "change",
    [{'email': 'a@b.c'}, {'message': 'mmmmmmmmmm'}, {'message': ''}, {'score': 0}, {'score': 10}],
)
def test_edges_are_valid(client: TestClient, change: dict[str, object]) -> None:
    assert client.post("/feedback", json={**OK, **change}).status_code == 200


@pytest.mark.parametrize(
    "change",
    [{'email': 'ada'}, {'email': 'a@b'}, {'email': '@b.c'}, {'email': 'a b@c.d'}, {'message': 'mmmmmmmmm'}, {'message': ''}, {'message': ''}, {'score': -1}, {'score': 11}],
)
def test_rule_breaks_are_422(client: TestClient, change: dict[str, object]) -> None:
    r = client.post("/feedback", json={**OK, **change})
    assert r.status_code == 422
    assert r.json()["error"]["kind"] == "ValidationError"


def test_missing_field_is_422(client: TestClient) -> None:
    first = next(iter(OK))
    assert client.post("/feedback", json={first: OK[first]}).status_code == 422
